/**
 * The screen shown while the app swaps itself for a downloaded update, and again on the first start after one.
 * A mascot animation, no text and no numbers: the helmet is not spun or loaded, it is drawn again over itself
 * (a "refit"), with a small click as each eye turns. Blackthorn Ink line art on Mist Green; the pen tip is Forest
 * Black, a touch heavier than the line (Spring Verdant has no contrast on Mist Green). Pure inline SVG and CSS: no script, no library, no file or
 * network request, so it paints at once and costs nothing. Only transform, opacity and stroke-dashoffset animate.
 *
 * The page is visible by default (the Rose Alloy twin is on screen from the first frame); the motion only adds.
 * Under prefers-reduced-motion it is a still helmet.
 */

export const UPDATE_SPLASH_SIZE = { width: 360, height: 260 } as const
// One screen for light and dark: the app icon's Mist Green ground and Blackthorn Ink line art. Flat, so the window's
// own backgroundColor matches it exactly and nothing flashes.
export const UPDATE_SPLASH_BACKGROUND = '#D5E6DC'

